import{_ as r,a0 as o,w as i,s as l,I as p,x as a,a1 as n,A as s,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"極速蝸牛：apt-fast | LCTT x X-CMD","titleTemplate":false,"description":"極速蝸牛：apt-fast | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"極速蝸牛：apt-fast | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"極速蝸牛：apt-fast | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141008 How to speed up slow apt-get install on Debian or Ubuntu","title":"極速蝸牛：apt-fast","tag":"201411","desc":""},"relativePath":"201411/20141008 How to speed up slow apt-get install on Debian or Ubuntu.md","filePath":"[post].md"}'),d={name:"201411/20141008 How to speed up slow apt-get install on Debian or Ubuntu.md"};function f(b,t,m,g,h,c){const e=o("Link");return i(),l("div",null,[t[24]||(t[24]=p("h1",{id:"極速蝸牛-apt-fast",tabindex:"-1"},[a("極速蝸牛：apt-fast "),p("a",{class:"header-anchor",href:"#極速蝸牛-apt-fast","aria-label":"Permalink to “極速蝸牛：apt-fast”"},"​")],-1)),t[25]||(t[25]=p("p",null,[a("如果你在Debian或Ubuntu系統上經常感覺到"),p("strong",null,"apt-get"),a(" 或 "),p("strong",null,"aptitude"),a("包安裝速度過慢，那麼這裏就有幾種改善這一情況的方法。你有沒有考慮過改變正被使用的默認鏡像站點？你有沒有排除因特網連接的上游帶寬成為瓶頸的可能？")],-1)),p("p",null,[t[2]||(t[2]=a("如果不是這些原因，你可以嘗試第三個選擇：使用",-1)),n(e,{href:"https://github.com/ilikenwf/apt-fast"},{default:s(()=>[...t[0]||(t[0]=[a("apt-fast",-1)])]),_:1}),t[3]||(t[3]=a("工具。apt-fast實際上是一個圍繞apt-get和aptitude所寫的shell腳本容器，它能加速包的下載速度。apt-fast本質上採用",-1)),n(e,{href:"http://aria2.sourceforge.net/"},{default:s(()=>[...t[1]||(t[1]=[a("aria2",-1)])]),_:1}),t[4]||(t[4]=a("下載工具，這款工具能夠以“塊”的方式從多個鏡像並行下載一個文件（就像BitTorrent下載）。",-1))]),t[26]||(t[26]=u(`<h3 id="在debian或ubuntu上安裝apt-fast" tabindex="-1">在Debian或Ubuntu上安裝apt-fast <a class="header-anchor" href="#在debian或ubuntu上安裝apt-fast" aria-label="Permalink to “在Debian或Ubuntu上安裝apt-fast”">​</a></h3><p>下面是在基於Debian的Linux上安裝apt-fast的步驟</p><h3 id="debian" tabindex="-1">Debian <a class="header-anchor" href="#debian" aria-label="Permalink to “Debian”">​</a></h3><pre><code>$ sudo apt-get install aria2
$ wget https://github.com/ilikenwf/apt-fast/archive/master.zip
$ unzip master.zip
$ cd apt-fast-master
$ sudo cp apt-fast /usr/bin
$ sudo cp apt-fast.conf /etc
$ sudo cp ./man/apt-fast.8 /usr/share/man/man8
$ sudo gzip /usr/share/man/man8/apt-fast.8
$ sudo cp ./man/apt-fast.conf.5 /usr/share/man/man5
$ sudo gzip /usr/share/man/man5/apt-fast.conf.5
</code></pre><h3 id="ubuntu-14-04-以及更高版本" tabindex="-1">Ubuntu 14.04 以及更高版本 <a class="header-anchor" href="#ubuntu-14-04-以及更高版本" aria-label="Permalink to “Ubuntu 14.04 以及更高版本”">​</a></h3><pre><code>$ sudo add-apt-repository ppa:saiarcot895/myppa
$ sudo apt-get update
$ sudo apt-get install apt-fast
</code></pre><h3 id="ubuntu-11-04-到-ubuntu-13-10" tabindex="-1">Ubuntu 11.04 到 Ubuntu 13.10 <a class="header-anchor" href="#ubuntu-11-04-到-ubuntu-13-10" aria-label="Permalink to “Ubuntu 11.04 到 Ubuntu 13.10”">​</a></h3><pre><code>$ sudo add-apt-repository ppa:apt-fast/stable
$ sudo apt-get update
$ sudo apt-get install apt-fast
</code></pre><p>在安裝期間，你需要選擇一個默認的軟件包管理器 (e.g., apt-get. aptitude )，還需要設置其餘選項。但是你可以隨時通過編輯配置文件 /etc/apt-fast/conf 來更改設置。</p><p><img src="https://farm6.staticflickr.com/5615/15285526898_1b18f64d58_z.jpg" alt=""></p><p><img src="https://farm3.staticflickr.com/2949/15449069896_76ee00851b_z.jpg" alt=""></p><p><img src="https://farm6.staticflickr.com/5600/15471817412_9ef7f16096_z.jpg" alt=""></p><h3 id="配置-apt-get" tabindex="-1">配置 apt-get <a class="header-anchor" href="#配置-apt-get" aria-label="Permalink to “配置 apt-get”">​</a></h3><p>安裝完成後，你需要在/etc/apt-fast.conf裏配置<strong>apt-fast</strong>使用的一系列鏡像。</p><p>你可以在下面的URL中找到一系列Debian/Ubuntu鏡像。</p>`,15)),p("ul",null,[p("li",null,[t[6]||(t[6]=p("strong",null,"Debian",-1)),t[7]||(t[7]=a(": ",-1)),n(e,{href:"http://www.debian.org/mirror/list"},{default:s(()=>[...t[5]||(t[5]=[a("http://www.debian.org/mirror/list",-1)])]),_:1})]),p("li",null,[t[9]||(t[9]=p("strong",null,"Ubuntu",-1)),t[10]||(t[10]=a(": ",-1)),n(e,{href:"https://launchpad.net/ubuntu/+archivemirrors"},{default:s(()=>[...t[8]||(t[8]=[a("https://launchpad.net/ubuntu/+archivemirrors",-1)])]),_:1})])]),t[27]||(t[27]=u(`<p>選擇完那些地理上靠近你的鏡像後，你需按照下面的格式將選擇的鏡像加入到/etc/apt-fast.conf。</p><pre><code>$ sudo vi /etc/apt-fast.conf
</code></pre><p>Debian：</p><pre><code>MIRRORS=(&#39;http://ftp.us.debian.org/debian/,http://carroll.aset.psu.edu/pub/linux/distributions/debian/,http://debian.gtisc.gatech.edu/debian/,http://debian.lcs.mit.edu/debian/,http://mirror.cc.columbia.edu/debian/&#39;)
</code></pre><p>Ubuntu/Mint：</p><pre><code>MIRRORS=(&#39;http://us.archive.ubuntu.com/ubuntu,http://mirror.cc.columbia.edu/pub/linux/ubuntu/archive/,http://mirror.cc.vt.edu/pub2/ubuntu/,http://mirror.umd.edu/ubuntu/,http://mirrors.mit.edu/ubuntu/&#39;)
</code></pre><p>如上面所示，對於一個特定檔案的個別鏡像，需要用逗號分割開來。你需要在/etc/apt/sources.list的MIRRORS字符串中包含默認的鏡像指定站點。</p><h3 id="使用apt-fast安裝一個包" tabindex="-1">使用apt-fast安裝一個包 <a class="header-anchor" href="#使用apt-fast安裝一個包" aria-label="Permalink to “使用apt-fast安裝一個包”">​</a></h3><p>現在你就可以測試apt-fast的強大了。下面是使用<strong>apt-fast</strong>的示例：</p><pre><code>apt-fast [apt-get options and arguments]
apt-fast [aptitude options and arguments]
apt-fast { { install | upgrade | dist-upgrade | build-dep | download  | source  } [ -y | --yes | --assume-yes | --assume-no ]   ... | clean }
</code></pre><p>使用<strong>apt-fast</strong>安裝包：</p><pre><code> $ sudo apt-fast install texlive-full
</code></pre><p>在當前目錄下載軟件包，但不安裝：</p><pre><code> $ sudo apt-fast download texlive-full
</code></pre><p><img src="http://farm8.staticflickr.com/7309/10585846956_6c98c6dcc9_z.jpg" alt=""></p><p>如前面所示，apt-fast的並行下載是通過aria2完成的。你可以看到如下圖般從多個鏡像並行下載。</p><pre><code>$ sudo netstat -nap | grep aria2c
</code></pre><p><img src="http://farm8.staticflickr.com/7328/10585846886_4744a0e021_z.jpg" alt=""></p><p>請注意，<strong>apt-fast</strong>並沒有加速&quot;apt-get update&quot;。並行下載只在&quot;install&quot;, &quot;upgrade&quot;, &quot;dist-upgrage&quot;和&quot;build-dep&quot;操作中觸發。其餘的操作，apt-fast就會簡單地回到默認的包管理器apt-get或aptitude。</p><h3 id="apt-fast有多快" tabindex="-1">apt-fast有多快？ <a class="header-anchor" href="#apt-fast有多快" aria-label="Permalink to “apt-fast有多快？”">​</a></h3><p>為了比較apt-fast和apt-get，我嘗試在兩個相同的Ubuntu實例上使用兩種方法安裝幾個軟件包。下面的圖表展示了所有軟件包安裝的時間(單位為秒)。</p><p><img src="http://farm4.staticflickr.com/3810/10585846986_504d07b4a7_z.jpg" alt=""></p><p>正如你所見到的，<strong>apt-fast</strong>確實比<strong>apt-get</strong>快(e.g. 快3--4秒)，特別是安裝龐大軟件包的時候。</p><p>當然，安裝性能的提高程度還依賴你上游因特網連通性。以我為例，我有富足的帶寬來支持我的上游連接。這也是為什麼我看到並行下載帶來了成功的提高。</p><hr>`,25)),p("p",null,[t[12]||(t[12]=a("via: ",-1)),n(e,{href:"http://xmodulo.com/speed-slow-apt-get-install-debian-ubuntu.html"},{default:s(()=>[...t[11]||(t[11]=[a("http://xmodulo.com/speed-slow-apt-get-install-debian-ubuntu.html",-1)])]),_:1})]),p("p",null,[t[16]||(t[16]=a("作者：",-1)),n(e,{href:"http://xmodulo.com/author/nanni"},{default:s(()=>[...t[13]||(t[13]=[a("Dan Nanni",-1)])]),_:1}),t[17]||(t[17]=a(" 譯者：",-1)),n(e,{href:"https://github.com/su-kaiyao"},{default:s(()=>[...t[14]||(t[14]=[a("su-kaiyao",-1)])]),_:1}),t[18]||(t[18]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[15]||(t[15]=[a("wxy",-1)])]),_:1})]),p("p",null,[t[21]||(t[21]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[19]||(t[19]=[a("LCTT",-1)])]),_:1}),t[22]||(t[22]=a(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:s(()=>[...t[20]||(t[20]=[a("Linux中國",-1)])]),_:1}),t[23]||(t[23]=a(" 榮譽推出",-1))])])}const $=r(d,[["render",f]]);export{w as __pageData,$ as default};
